const gemini = $input.first().json;
const raw = gemini?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  // Fall back to safe defaults if Gemini drifts from JSON
  parsed = {
    intent: 'handoff',
    response_text: 'Thanks — let me get one of our team to follow up with you shortly.',
    order_query: null,
    ticket: null,
    handoff_reason: 'Model returned non-JSON; routing to human for safety.'
  };
}

const valid = ['qa', 'order_lookup', 'ticket_create', 'handoff'];
if (!valid.includes(parsed.intent)) parsed.intent = 'qa';

const prev = $('Build Gemini Prompt').item.json;

return [{ json: {
  conversation_id: prev.conversation_id,
  customer_email: prev.customer_email,
  user_message: prev.user_message,
  intent: parsed.intent,
  response_text: parsed.response_text || '',
  order_query: parsed.order_query || null,
  ticket: parsed.ticket || null,
  handoff_reason: parsed.handoff_reason || null
} }];

