// Pull the original Gemini-parse output (carries intent + draft response_text)
const parsed = $('Parse Gemini Output').item.json;
let finalText = parsed.response_text || '';

// Branch-specific substitutions
if (parsed.intent === 'order_lookup') {
  // Pull all rows from Lookup Order
  const rows = $('Lookup Order').all().map(i => i.json);
  let orderBlock;
  if (!rows.length) {
    orderBlock = "I couldn't find any orders matching that. Could you double-check the order number, or share the email used to place it?";
  } else {
    orderBlock = rows.map(r => {
      const total = (r.total_cents / 100).toFixed(2);
      const tracking = r.tracking_url ? `\n  Tracking: ${r.tracking_url}` : '';
      return `• Order ${r.order_number} — ${r.status} — ${r.currency} ${total}${tracking}`;
    }).join('\n');
  }
  finalText = finalText.replace('{{ORDER_DETAILS}}', orderBlock);
}

if (parsed.intent === 'ticket_create') {
  const ticket = $('Create Ticket').item.json;
  finalText = finalText.replace('{{TICKET_ID}}', String(ticket.id || '???'));
}

// qa and handoff: response_text from Gemini is already final.

return [{ json: {
  conversation_id: parsed.conversation_id,
  intent: parsed.intent,
  response_text: finalText,
  ticket_id: parsed.intent === 'ticket_create' ? $('Create Ticket').item.json.id : null,
  order_count: parsed.intent === 'order_lookup' ? $('Lookup Order').all().length : null
} }];
